import 'dart:convert';

/// Diport dari policy-data SkinSight Rule Lab v1.3 (bukan aturan baru).
/// Batas angka dan durasi adalah heuristik pemantauan prototipe, bukan severity
/// klinis atau perkiraan sembuh. Konten mingguan merujuk research ID pada policy.
abstract final class SkinTimelinePolicy {
  static final Map<String, dynamic> data =
      jsonDecode(_json) as Map<String, dynamic>;
  static const String _json =
      r'''{"schema_version":"1.0.0","status":"DRAFT_MVP_HEURISTIC_NOT_CLINICALLY_VALIDATED","principles":{"timeline_basis":"One weekly global date from first saved baseline; each class independently uses a tracking cycle from its first valid detection.","counts_are_not_severity":true,"planned_weeks_are_ux_not_cure":true,"manual_confirm":true,"future_events_are_plan_not_predictions":true,"do_not_auto_prescribe":true,"no_hplus1":true,"no_extra_footer_tab":true,"no_new_quiz_questions":true},"sources":{"NICE_ACNE":{"name":"NICE NG198 Acne vulgaris management","url":"https://www.nice.org.uk/guidance/ng198/chapter/Recommendations","supports":"6–8 minggu mulai terlihat pada sebagian perawatan; tinjau 12 minggu; klasifikasi lesi klinis bukan bounding box umum."},"AAD_ACNE":{"name":"AAD: painful deep acne","url":"https://www.aad.org/news/how-to-treat-painful-pimple-home","supports":"Hindari memencet jerawat dalam; nyeri berat, risiko jaringan parut perlu evaluasi."},"PHOTO_ACNE":{"name":"Picture-based acne lesion counts validation (2022)","url":"https://pubmed.ncbi.nlm.nih.gov/36161460/","supports":"Hitung lesi dari foto dengan metodologi terstandar; tidak memberi ambang 4 vs 6."},"AAD_PIH":{"name":"AAD: How to fade dark spots in darker skin tones","url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots","supports":"Perlindungan UV, sunscreen tinted iron oxide; beberapa noda dapat memudar 6–12 bulan setelah penyebab dikendalikan, bukan prediksi individu."},"PIH_RCT":{"name":"RCT Azelaic Acid for PIH and PIE (2024)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11116308/","supports":"Pengukuran pada minggu 0,4,8,12 untuk regimen spesifik, bukan siklus semua PIH."},"PIH_APIG":{"name":"Acne-induced PIH from grading to treatment (2025): APIG proposed","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12041799/","supports":"Usulan indeks memperhitungkan noda ≤5 vs >5 bersama ukuran, intensitas, durasi dan fototipe; tidak mendukung lama timeline berdasar count sendiri."},"DC_REVIEW":{"name":"Periorbital Hyperpigmentation: A Comprehensive Review","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4756872/","supports":"Penyebab pigmentasi, vaskular, struktural, campuran; tak ada lama pengobatan universal."},"AAD_RED":{"name":"AAD 7 rosacea skin care tips","url":"https://www.aad.org/public/diseases/rosacea/triggers/tips","supports":"Kulit kemerahan mudah teriritasi; edukasi perawatan lembut, pelembap, UV; tidak semua redness rosacea."},"WR_REVIEW":{"name":"Systematic review tretinoin photoaging RCT (2022)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9112391/","supports":"Studi fotoaging retinoid sepanjang beberapa bulan; bukan rekomendasi otomatis dan bukan timeline berdasar mask."},"WSRS":{"name":"WSRS wrinkle severity rating validation","url":"https://pubmed.ncbi.nlm.nih.gov/14979743/","supports":"Skala klinis lipatan nasolabial 1–5; bukan persentase luas mask seluruh wajah."},"DOC_V04":{"name":"SkinSight internal MVP v0.4","url":null,"supports":"Tujuh pertanyaan M01–M07, satu check-in per minggu, lima kelas independen, tidak ada skor penyembuhan."}},"classes":{"acne":{"metric":"count","source_ids":["NICE_ACNE","AAD_ACNE","PHOTO_ACNE"],"bands":[{"min":1,"max":4,"code":"A_LOW","weeks":4,"extension_weeks":4,"focus":"Jumlah objek relatif sedikit pada foto contoh; pantau perubahan jumlah dan keluhan tanpa memberi label tingkat keparahan.","stage_messages":{"start":"Catat 1–4 objek sebagai hasil teknis awal; tidak otomatis ringan secara medis.","first_checkin":"Periksa apakah area yang sedikit ini terfoto jelas; kuis tetap menanyakan keluhan dan perawatan.","early":"Jika ada foto baru, bandingkan jumlah persisnya; jangan menyimpulkan dari selisih satu objek saja.","middle":"Ringkas laporan pengguna dan variasi hitungan, bukan perubahan penyakit.","review":"Tinjau empat minggu awal; jika temuan atau kekhawatiran masih ada, jadwalkan observasi lanjutan.","extension":"Cek hasil baru jika siklus diperpanjang, tanpa mengubah rekomendasi medis."}},{"min":5,"max":9,"code":"A_MID","weeks":8,"extension_weeks":4,"focus":"Lebih banyak objek terdeteksi; utamakan cakupan foto yang konsisten dan riwayat keluhan.","stage_messages":{"start":"Catat 5–9 objek; perhatikan konsistensi lokasi dan cakupan wajah.","first_checkin":"Verifikasi kondisi foto seluruh area yang terdeteksi; catat keluhan pada kuis, bukan asumsi tingkat parah.","early":"Perhatikan sebaran objek dan riwayat perawatan yang dilaporkan.","middle":"Bandingkan hitungan pada ROI yang sama; cek apakah foto tambahan tersedia dan setara.","review":"Tinjau delapan minggu awal, perhatikan ketidakpastian dan laporan efek samping.","extension":"Dalam siklus tambahan, cek observasi baru dan keluhan pengguna tanpa menaikkan terapi otomatis."}},{"min":10,"max":null,"code":"A_HIGH","weeks":12,"extension_weeks":4,"focus":"Objek terdeteksi lebih banyak; tampilkan laporan nyeri/jaringan parut bila ada. Jumlah ini tetap bukan skor klinis.","stage_messages":{"start":"Catat ≥10 objek sebagai jumlah hasil AI; tidak menyetarakan dengan kategori klinis NICE.","first_checkin":"Utamakan pencatatan keluhan nyeri/jaringan parut jika pengguna mengungkapkannya; foto saja tidak memastikan.","early":"Catat jumlah setiap minggu dengan QC ketat; pesan keselamatan mengalahkan progres angka.","middle":"Tinjau kesebandingan foto dan kepatuhan perawatan yang benar-benar dilaporkan.","review":"Tinjau dua belas minggu observasi; tanggal review pengobatan tetap terpisah dari tanggal scan.","extension":"Lanjutkan dokumentasi jika masih ada temuan/keluhan; bukan prediksi kegagalan terapi."}}],"weekly":["Catat jumlah objek yang terlihat dan jelaskan perawatan wajah lembut serta risiko memencet lesi.","Tinjau keluhan perih, kering, panas, atau mengelupas; jangan menganggap pengguna sudah memulai pengobatan.","Tinjau konsistensi penggunaan perawatan yang benar-benar dilaporkan (M01, M02); hindari kesimpulan gagal dari satu minggu.","Bandingkan angka temuan dengan foto sebelumnya hanya bila pose, area, kualitas, dan versi model sebanding.","Buat ringkasan empat minggu: angka pada foto dan laporan pengguna ditulis terpisah.","Tinjau apakah pengguna mengubah perawatan; simpan tanggal perubahan bila dilaporkan.","Periksa toleransi dan perubahan hitungan; acuan efek 6–8 minggu hanya muncul jika regimen Acne relevan sudah berlangsung selama itu.","Jika hasil naik/turun, tampilkan selisih objek terdeteksi, bukan persentase kesembuhan.","Jika regimen Acne relevan sudah berlangsung 8 minggu, tampilkan acuan studi 6–8 minggu; jika tidak, hanya rekap observasi.","Tinjau keluhan baru termasuk nyeri dalam atau kekhawatiran jaringan parut; tampilkan evaluasi profesional jika dilaporkan.","Bandingkan angka saat ini dengan baseline dengan standar foto identik, atau tandai tidak dapat dibandingkan.","Periksa apakah ada perubahan perawatan atau iritasi yang belum tercatat sebelum ringkasan siklus.","Pada 12 minggu dari awal regimen relevan, tampilkan konteks peninjauan NICE; jika tidak, tampilkan ringkasan observasi biasa."],"additional_weeks":{"13":"Tinjau hasil evaluasi yang dilaporkan pengguna bila ada; jangan berasumsi terapi diubah.","14":"Pantau hitungan objek terdeteksi dan laporan nyeri/jaringan parut secara terpisah.","15":"Tinjau apakah foto dapat dibandingkan dengan sesi sebelumnya.","16":"Rekap siklus tambahan dengan data nyata dan laporan pengguna, bukan perkiraan sembuh."},"weekly_evidence_ids":["AAD_ACNE","NICE_ACNE","NICE_ACNE","PHOTO_ACNE","PHOTO_ACNE","NICE_ACNE","NICE_ACNE","PHOTO_ACNE","NICE_ACNE","AAD_ACNE","PHOTO_ACNE","NICE_ACNE","NICE_ACNE"],"metric_threshold_status":"PRODUCT_UX_UNVALIDATED_NOT_A_DIAGNOSTIC_CUTOFF"},"pih":{"metric":"count","source_ids":["AAD_PIH","PIH_RCT","PIH_APIG"],"bands":[{"min":1,"max":5,"code":"P_LOW","weeks":8,"extension_weeks":8,"focus":"Catat noda yang terdeteksi; prioritas edukasi UV dan riwayat iritasi.","stage_messages":{"start":"Catat 1–5 noda sebagai hasil deteksi; jangan mengklaim skor PAHPI.","first_checkin":"Tinjau kebiasaan sunscreen sesuai M05 untuk jumlah noda yang terlihat saat ini.","early":"Catat noda baru jika model layak dan foto sebanding.","middle":"Periksa catatan UV, iritasi dan foto perbandingan, bukan estimasi pemudaran.","review":"Tinjau delapan minggu observasi; noda tersisa bukan otomatis kegagalan perawatan.","extension":"Perpanjang pemantauan bila dibutuhkan data tambahan; jadwal pemudaran tidak diprediksi."}},{"min":6,"max":11,"code":"P_MID","weeks":12,"extension_weeks":8,"focus":"Lebih dari lima noda tampak; tampilkan angka dan foto dengan hati-hati, bukan skor PAHPI.","stage_messages":{"start":"Catat 6–11 noda; ambang >5 hanya satu unsur usulan APIG, bukan ukuran tingkat klinis.","first_checkin":"Prioritaskan dokumentasi UV dan iritasi; jangan menyimpulkan keparahan dari angka enam saja.","early":"Bandingkan noda dengan pencahayaan/area yang setara agar pembacaan angka tidak menipu.","middle":"Tinjau kuesioner perawatan yang dilaporkan dan jumlah noda pada foto baru.","review":"Tinjau dua belas minggu pemantauan; acuan studi berlaku khusus regimen relevan.","extension":"Lanjutkan bila noda dan kekhawatiran tercatat; tetap hindari prediksi tanggal hilang."}},{"min":12,"max":null,"code":"P_HIGH","weeks":24,"extension_weeks":8,"focus":"Lebih banyak noda tampak; foto dan riwayat UV menjadi fokus pengamatan, bukan tingkat keparahan klinis.","stage_messages":{"start":"Catat ≥12 noda; cek duplikasi objek dan kualitas foto sebelum percaya perbedaan hitungan.","first_checkin":"Fokus pada pencatatan faktor UV dan reaksi produk; jangan menyusun resep dari jumlah noda.","early":"Jika foto berbeda pencahayaan, tampilkan status tidak bisa dibandingkan.","middle":"Ringkas beberapa sesi dan status perlindungan UV sesuai jawaban pengguna.","review":"Tinjau observasi 24 minggu; edukasi AAD 6–12 bulan bukan tenggat sembuh.","extension":"Lanjutkan observasi untuk noda yang masih menjadi perhatian pengguna."}}],"weekly":["Catat jumlah noda terdeteksi; tampilkan edukasi perlindungan matahari dan menghindari pemicu peradangan.","Gunakan jawaban M05 untuk menyesuaikan informasi perlindungan UV; jangan mengasumsikan sunscreen sudah rutin.","Tinjau riwayat produk yang mengiritasi (M04) dan pemicu noda yang dilaporkan pengguna.","Perbandingan noda membutuhkan pose dan pencahayaan sebanding; angka tidak sama dengan derajat pigmentasi.","Jika regimen PIH tercatat minimal 4 minggu, tampilkan bahwa studi tertentu menilai pada minggu 4; bukan prediksi noda memudar.","Catat perlindungan UV yang dilaporkan; hindari mengharapkan perubahan warna dalam seminggu.","Ringkas perubahan jumlah noda yang terlihat hanya untuk foto berkualitas sebanding.","Tinjau kemungkinan munculnya noda baru dan iritasi berdasarkan laporan pengguna.","Jika regimen PIH relevan mencapai 8 minggu, tampilkan titik pengukuran minggu 8 pada RCT terkait.","Tinjau M05 dan dokumentasikan aktivitas perlindungan matahari yang benar-benar dilaporkan.","Bandingkan jumlah dan area jika model menyediakan ukuran; tidak memaksakan skor PAHPI dari jumlah saja.","Tinjau perawatan dan efek iritasi sebelum ringkasan periode.","Jika regimen PIH relevan mencapai 12 minggu, tampilkan evaluasi studi 12 minggu; tidak meresepkan kelanjutan terapi."],"additional_weeks":{"13":"Tinjau kebiasaan perlindungan UV terakhir yang dilaporkan.","14":"Cek perbandingan noda hanya pada foto layak dan pencahayaan serupa.","15":"Tinjau produk yang pernah dilaporkan menimbulkan iritasi.","16":"Rekap pengamatan bulan ke-4; sebagian PIH memerlukan waktu lama.","17":"Tinjau perubahan noda baru berdasarkan observasi dan laporan pengguna.","18":"Catat konsistensi penggunaan sunscreen sesuai jawaban terbaru.","19":"Tinjau apakah model dan area pengambilan foto masih konsisten.","20":"Bandingkan jumlah/area jika data sebanding; jangan mengubahnya menjadi PAHPI.","21":"Periksa apakah perawatan yang dilaporkan berubah sejak awal siklus.","22":"Tinjau keluhan iritasi yang dilaporkan; jangan menambah bahan aktif otomatis.","23":"Siapkan rekap siklus berdasarkan hasil foto yang layak dan laporan pengguna.","24":"Rekap pengamatan 24 minggu; 6–12 bulan adalah konteks PIH, bukan tanggal sembuh."},"weekly_evidence_ids":["AAD_PIH","AAD_PIH","AAD_PIH","DOC_V04","PIH_RCT","AAD_PIH","DOC_V04","AAD_PIH","PIH_RCT","AAD_PIH","PIH_APIG","DOC_V04","PIH_RCT"],"metric_threshold_status":"PRODUCT_UX_UNVALIDATED_NOT_A_DIAGNOSTIC_CUTOFF"},"dark_circle":{"metric":"count","source_ids":["DC_REVIEW"],"bands":[{"min":1,"max":1,"code":"D_LOW","weeks":4,"extension_weeks":4,"focus":"Satu area temuan; perhatikan efek bayangan/pencahayaan.","stage_messages":{"start":"Satu temuan bawah mata; periksa apakah bayangan atau kondisi cahaya memengaruhi hasil.","first_checkin":"Fokus foto pembanding area yang sama; tidak menentukan penyebab dari satu box.","early":"Catat kesan pengguna dan perubahan pencahayaan secara terpisah.","middle":"Bandingkan foto bila layak; informasi penyebab tetap belum pasti.","review":"Tinjau empat minggu observasi tanpa target sembuh.","extension":"Lanjutkan hanya sebagai dokumentasi pengamatan."}},{"min":2,"max":2,"code":"D_MID","weeks":8,"extension_weeks":4,"focus":"Dua area temuan; pantau kiri-kanan tanpa menyimpulkan etiologi.","stage_messages":{"start":"Dua area temuan; jangan otomatis menyimpulkan satu sebab pada kedua mata.","first_checkin":"Periksa posisi kiri/kanan dan cahaya pada foto baru.","early":"Catat laporan pengguna dan variasi kedua area.","middle":"Tinjau apakah perbedaan sisi dapat dijelaskan posisi kamera.","review":"Tinjau delapan minggu observasi, bukan efektivitas terapi tanpa diagnosis.","extension":"Lanjutkan dengan perhatian pada ketidakpastian penyebab."}},{"min":3,"max":null,"code":"D_HIGH","weeks":12,"extension_weeks":4,"focus":"Beberapa kotak pada area mata; verifikasi duplikasi box dan kualitas foto karena angka bukan derajat Dark Circle.","stage_messages":{"start":"Tiga atau lebih box pada area bawah mata; cek potensi tumpang tindih deteksi.","first_checkin":"Periksa quality gate; jumlah box yang banyak bisa mencerminkan duplikasi.","early":"Catat area berbeda bila benar-benar lolos inspeksi data.","middle":"Perbandingan antar foto perlu ROI, cahaya dan versi model konsisten.","review":"Tinjau dua belas minggu observasi, tidak membentuk skor tingkat Dark Circle.","extension":"Lanjutkan hanya jika data layak dan pengguna menginginkan pemantauan."}}],"weekly":["Catat temuan area bawah mata; jelaskan beragam kemungkinan sebab tanpa menyimpulkan penyebab individual.","Untuk observasi, gunakan pencahayaan dan pose konsisten agar bayangan tidak menipu hasil.","Jangan otomatis memilih bahan pencerah dekat mata; faktor pigmentasi, vaskular, dan struktur berbeda.","Catat perubahan menurut pengguna tanpa menyamakan bayangan foto dengan perubahan medis.","Tinjau foto yang dapat dibandingkan dan keluhan mata; jika keluhan berat, prioritaskan pertolongan profesional.","Tinjau apakah jumlah temuan berubah karena kamera atau pencahayaan.","Catat kondisi menurut pengguna dan pastikan informasi tidak menyebut tanggal sembuh.","Bandingkan foto tampak depan yang layak; tampilkan ketidakpastian bila area mata tertutup.","Buat ringkasan observasi tanpa menjanjikan hilangnya lingkaran gelap.","Periksa adanya keluhan baru yang dilaporkan; jangan menyimpulkan penyebab dari hasil deteksi.","Tinjau kualitas pencahayaan foto dari waktu ke waktu.","Simpan perubahan yang diamati beserta status tidak pasti jika data bertentangan.","Tinjau siklus pemantauan; penyebab dark circle belum bisa ditentukan dari model ini."],"additional_weeks":{"13":"Cek konsistensi pose dan cahaya saat membandingkan temuan bawah mata.","14":"Catat keluhan baru bila dilaporkan; penyebab belum bisa dipastikan.","15":"Jangan menganggap perbedaan bayangan foto sebagai respons terapi.","16":"Tinjau akhir siklus tambahan tanpa prediksi lama pulih."},"weekly_evidence_ids":["DC_REVIEW","DC_REVIEW","DC_REVIEW","DOC_V04","DC_REVIEW","DOC_V04","DC_REVIEW","DOC_V04","DC_REVIEW","DC_REVIEW","DOC_V04","DOC_V04","DC_REVIEW"],"metric_threshold_status":"PRODUCT_UX_UNVALIDATED_NOT_A_DIAGNOSTIC_CUTOFF"},"redness":{"metric":"mask_percent","source_ids":["AAD_RED"],"bands":[{"min":0,"max_exclusive":5,"code":"R_LOW","weeks":4,"extension_weeks":4,"focus":"Area mask kecil dalam foto; riwayat rasa perih/panas lebih penting untuk informasi keamanan.","stage_messages":{"start":"Luas mask <5% dari area valid; catat satuan dan wilayah yang dipakai.","first_checkin":"Keluhan perih/panas tetap perlu diperhatikan meski mask tampak kecil.","early":"Periksa apakah pencahayaan merah/putih memengaruhi mask.","middle":"Bandingkan foto valid, jangan beri derajat rosacea dari mask.","review":"Tinjau empat minggu observasi dan gejala terlapor.","extension":"Perpanjang hanya observasi teknis dan keluhan."}},{"min":5,"max_exclusive":15,"code":"R_MID","weeks":8,"extension_weeks":4,"focus":"Area mask lebih luas; perhatikan pemicu produk dan konsistensi warna/pencahayaan.","stage_messages":{"start":"Luas mask 5–<15% area valid; ini interval desain, bukan stadium klinis.","first_checkin":"Perhatikan riwayat bahan pemicu (M04) dan iritasi (M03).","early":"Uji stabilitas mask pada area dan cahaya serupa.","middle":"Catat jika keluhan bertambah meskipun persentase tampak sama.","review":"Tinjau delapan minggu observasi, bukan evaluasi pengobatan otomatis.","extension":"Lanjutkan catatan pemicu pengguna dan variasi mask."}},{"min":15,"max_exclusive":null,"code":"R_HIGH","weeks":12,"extension_weeks":4,"focus":"Area mask luas; tetap tidak memberi diagnosis atau derajat keparahan dari persen mask.","stage_messages":{"start":"Luas mask ≥15% area valid; bukan diagnosis rosacea atau indikasi obat.","first_checkin":"Prioritaskan keluhan sedang–berat yang dilaporkan dan keamanan pengguna.","early":"Hindari interpretasi beda warna akibat sumber cahaya.","middle":"Ringkas riwayat gejala dan perubahan foto yang sebanding.","review":"Tinjau dua belas minggu pengamatan; tidak prediksi pulih.","extension":"Jika keluhan serius, informasi evaluasi profesional tetap prioritas."}}],"weekly":["Catat luas mask kemerahan pada area valid; edukasi perawatan lembut dan pelembap.","Prioritaskan keluhan perih, panas, atau iritasi (M03/check-in), bukan perubahan mask semata.","Tinjau produk yang pernah memicu iritasi (M04) jika jawabannya ada.","Gunakan M05 untuk edukasi perlindungan UV; kemerahan tidak otomatis berarti rosacea.","Bandingkan luas mask dengan pencahayaan/area yang sebanding, dan pisahkan laporan gejala.","Tinjau efek perawatan yang benar-benar dilaporkan dan keluhan baru.","Catat apakah kemerahan hanya terlihat pada foto tertentu; jangan menganggapnya diagnosis.","Jika ada foto berulang, rangkum variasi hasil tanpa merata-ratakan lintas pose.","Tinjau perubahan laporan rasa perih atau panas serta area mask.","Jika keluhan menetap atau memburuk menurut pengguna, tampilkan opsi evaluasi profesional.","Periksa rekaman produk pemicu dari kuesioner awal dan pembaruan pengguna.","Bandingkan data terbaru dengan baseline secara hati-hati.","Tinjau siklus pemantauan; tidak ada milestone penyembuhan universal untuk redness."],"additional_weeks":{"13":"Tinjau perubahan keluhan perih/panas dan hasil area mask secara terpisah.","14":"Cek riwayat produk pemicu berdasarkan laporan pengguna.","15":"Tinjau apakah warna pencahayaan foto dapat memengaruhi mask.","16":"Rekap siklus tambahan; status medis tidak ditentukan dari persentase area."},"weekly_evidence_ids":["AAD_RED","AAD_RED","AAD_RED","AAD_RED","DOC_V04","AAD_RED","AAD_RED","DOC_V04","AAD_RED","AAD_RED","AAD_RED","DOC_V04","AAD_RED"],"metric_threshold_status":"PRODUCT_UX_UNVALIDATED_NOT_A_DIAGNOSTIC_CUTOFF"},"wrinkle":{"metric":"mask_percent","source_ids":["WR_REVIEW","WSRS"],"bands":[{"min":0,"max_exclusive":5,"code":"W_LOW","weeks":8,"extension_weeks":8,"focus":"Area mask kecil; perhatikan pose/ekspresi wajah serta perlindungan UV.","stage_messages":{"start":"Luas mask <5%; foto tidak mengukur kedalaman klinis kerutan.","first_checkin":"Utamakan foto ekspresi wajah netral dan UV yang dilaporkan.","early":"Periksa variasi ekspresi/pose sebelum menafsirkan perbedaan mask.","middle":"Tinjau perubahan yang tercatat dan perawatan tanpa memprediksi perbaikan.","review":"Tinjau delapan minggu observasi; riset terapi punya periode tersendiri.","extension":"Lanjutkan jika pengguna memilih pemantauan lebih panjang."}},{"min":5,"max_exclusive":15,"code":"W_MID","weeks":12,"extension_weeks":8,"focus":"Area mask menengah; buat observasi foto dengan ekspresi yang sama.","stage_messages":{"start":"Luas mask 5–<15%; fokus konsistensi ROI dan ekspresi.","first_checkin":"Periksa kualitas foto dan M05 sunscreen, bukan jumlah masker saja.","early":"Dokumentasikan area dan model sebelum membandingkan hasil.","middle":"Tinjau laporan iritasi jika ada perawatan yang dicatat.","review":"Tinjau dua belas minggu observasi; WSRS tidak bisa dihitung dari mask.","extension":"Lanjutkan dengan perbandingan foto netral."}},{"min":15,"max_exclusive":null,"code":"W_HIGH","weeks":24,"extension_weeks":8,"focus":"Area mask lebih luas; tetap bukan skala klinis wrinkle. Observasi lebih panjang adalah keputusan UX.","stage_messages":{"start":"Luas mask ≥15%; interval ini teknis bukan klasifikasi photoaging.","first_checkin":"Prioritaskan kualitas pose wajah dan dokumentasi perlindungan UV.","early":"Hasil baru sebaiknya memakai ekspresi dan area identik.","middle":"Catat toleransi bila pengguna menggunakan regimen tertentu.","review":"Tinjau 24 minggu pengamatan; tidak identik dengan durasi studi tretinoin.","extension":"Perpanjang jika ada minat dan data baru, tanpa estimasi terapi."}}],"weekly":["Catat luas mask Wrinkle yang terdeteksi; tampilkan edukasi perlindungan UV dan batas interpretasi foto.","Tinjau M05 agar pesan sunscreen sesuai kebiasaan yang sebenarnya.","Tekankan pose dan ekspresi netral ketika membandingkan kerutan wajah.","Jika tipe kulit Dry dan ada iritasi, tampilkan edukasi pelembap serta kehati-hatian.","Jika ada regimen photoaging relevan, sebutkan bahwa hasil penelitian dinilai dalam hitungan bulan; bukan menjanjikan hasil.","Bandingkan area mask hanya jika pose, ekspresi, dan area sebanding.","Tinjau apakah pengguna mengubah perawatan, tanpa merekomendasikan retinoid otomatis.","Periksa kualitas foto dan apakah ekspresi wajah konsisten.","Catat luas mask terbaru; perbedaan angka bukan kedalaman kerutan klinis.","Tinjau perlindungan UV dan laporan toleransi jika tersedia.","Bandingkan angka dengan baseline pada area wajah yang sama.","Tinjau data perawatan dan kemungkinan iritasi.","Jika regimen photoaging relevan telah berjalan beberapa bulan, tampilkan konteks studi; jika belum, hanya ringkasan pengamatan."],"additional_weeks":{"13":"Tinjau apakah foto terbaru memakai ekspresi dan posisi wajah netral.","14":"Catat perubahan area mask teknis, bukan kedalaman kerutan klinis.","15":"Tinjau kebiasaan perlindungan UV menurut M05.","16":"Jika ada regimen relevan, tampilkan konteks bahwa beberapa studi photoaging berlangsung berbulan-bulan.","17":"Tinjau apakah pengguna mencatat perubahan perawatan atau iritasi.","18":"Periksa perubahan area mask pada area wajah yang sama.","19":"Catat hasil baru tanpa prediksi perubahan kerutan individu.","20":"Periksa konsistensi perangkat, foto dan versi model.","21":"Tinjau apakah ada keluhan yang memerlukan perhatian kesehatan.","22":"Catat kegiatan perlindungan UV yang dilaporkan.","23":"Ringkas semua observasi yang benar-benar dapat dibandingkan.","24":"Rekap 24 minggu; rentang studi photoaging bukan perkiraan hasil individu."},"weekly_evidence_ids":["WR_REVIEW","WR_REVIEW","DOC_V04","DOC_V04","WR_REVIEW","DOC_V04","WR_REVIEW","DOC_V04","WSRS","WR_REVIEW","DOC_V04","WR_REVIEW","WR_REVIEW"],"metric_threshold_status":"PRODUCT_UX_UNVALIDATED_NOT_A_DIAGNOSTIC_CUTOFF"}},"quiz_map":{"M01":"current_care, care_name_optional, care_started_at_optional; research_eligible_care_is_validated_by_external_review (not implied by name alone)","M02":"care_adherence_last7d","M03":"irritation_level","M04":"prior_bad_reaction and optional ingredient_name","M05":"sunscreen_routine","M06":"under_doctor_care","M07":"priority_classes","weekly":"per_class_self_report, care_status, irritation_level, optional_photo","skin_type":"oily | dry | normal | combination | uncertain; content modifier only, no time change"},"engine_decisions":{"baseline":"At first valid finding per class select band; planned review cycle ends at class_start+band.weeks*7 days. This is a UX monitoring cycle, not a therapy/cure timer.","timeline":"Merge all class messages on one actual calendar check-in event; no duplicate check-in per class.","confidence":"Do not invent cutoff; if ML uncertain, no reliable baseline count and prompt retake or uncertain state.","safety":"Moderate-severe irritation or reported serious signs override routine content immediately and suggest prompt professional care; no automatic prescription changes.","photos":"Compare measurements only when camera pose, region, quality, and model_version are compatible; otherwise show incomparable, never interpolate missing values.","at_horizon":"Review current findings and report. If both consecutive comparable photos no longer detect this class AND latest user report is not worsening, mark tracking review complete (not cured); if still detected or user reports worsening/same/uncertain, extend next cycle by band.extension_weeks. If data inadequate, leave pending and extend a small review window.","regimen_timing":"NICE acne week6-8/12 or PIH study 4/8/12 or wrinkle study durations appear ONLY when named relevant care has known start date; never from baseline scan date.","never":"Never force a treatment, dose, complete cure, diagnosis, clinical severity or treatment length based on raw box or mask %.","changes":"At each check-in compare per-class latest valid observation to prior valid observation only if comparable. Report numeric difference and source as technical observations, not illness improvement. No scan => no new numeric point.","extension":"At an existing cycle end, if a confirmed check-in review shows ongoing finding/concern, extend by extension_weeks. Never pre-extend using hypothetical future results.","end":"Never mark medically cured. Use CYCLE_REVIEW_COMPLETE_NOT_CURED only if two comparable photos show zero AND user report is not worsening; missing data => REVIEW_PENDING_DATA.","later_content":"After longest predefined week, select report-driven content and clearly display no new data if absent; NEVER invent a new week-specific treatment. This fallback is executable, not clinical.","branch_focus":"Each week uses one stage_messages entry from the class numeric band, plus the week-specific evidence-based educational content. Band stage content is marked UX, not biomedical evidence."},"special_context_rules":{"M03_irritation_moderate_severe":{"priority":100,"text":"Keluhan iritasi sedang–berat: jangan menambah bahan aktif atas dasar hasil AI; pertimbangkan evaluasi tenaga kesehatan.","sources":["AAD_RED","NICE_ACNE"]},"M06_doctor_care_yes":{"priority":95,"text":"Sedang dalam perawatan dokter: ikuti arahan dokter; SkinSight tidak mengubah terapi.","sources":["NICE_ACNE"]},"M05_sunscreen_infrequent_PIH_or_wrinkle":{"priority":30,"text":"Perlindungan UV perlu diperhatikan; sesuaikan sunscreen yang nyaman dan sesuai kebutuhan.","sources":["AAD_PIH","WR_REVIEW"]},"M01_care_none":{"priority":20,"text":"Belum ada perawatan yang dilaporkan; jangan tampilkan evaluasi minggu terapi.","sources":["DOC_V04"]},"care_6_to_8w_acne":{"priority":20,"text":"Sebagian perawatan Acne mulai memperlihatkan efek 6–8 minggu; acuan berasal dari tanggal mulai perawatan yang dilaporkan.","sources":["NICE_ACNE"]},"care_12w_acne":{"priority":20,"text":"NICE merekomendasikan peninjauan terapi Acne sekitar 12 minggu bersama tenaga kesehatan.","sources":["NICE_ACNE"]},"care_4_8_12w_PIH":{"priority":20,"text":"RCT tertentu mengukur PIH pada minggu 4, 8, dan 12 terapi; ini bukan jaminan efek atau resep personal.","sources":["PIH_RCT"]},"care_months_wrinkle":{"priority":20,"text":"Beberapa studi photoaging menilai hasil selama beberapa bulan; tidak berarti kondisi pengguna pasti berubah sesuai studi.","sources":["WR_REVIEW"]}}}''';
